// src/retry-helper.ts
// 重试辅助：fn 最多尝试 attempts 次，全部失败抛最后一次错误
export async function withRetry<T>(fn: () => Promise<T>, attempts: number): Promise<T> {
  // 最多尝试 attempts 次（边界：attempts=3 恰好 3 次，attempts=0 一次不调）。
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

// tests/retry-helper.test.ts
import { describe, it, expect } from 'vitest';
import { withRetry } from '../src/retry-helper.js';

describe('withRetry', () => {
  it('首次成功只调用一次', async () => {
    let calls = 0;
    const r = await withRetry(async () => { calls += 1; return 'ok'; }, 3);
    expect(r).toBe('ok');
    expect(calls).toBe(1);
  });

  it('失败后重试成功', async () => {
    let calls = 0;
    const r = await withRetry(async () => {
      calls += 1;
      if (calls < 2) throw new Error('transient');
      return 'ok';
    }, 3);
    expect(r).toBe('ok');
    expect(calls).toBe(2);
  });

  it('全部失败时调用次数不超过 attempts（边界）', async () => {
    let calls = 0;
    await withRetry(async () => { calls += 1; throw new Error('fail'); }, 3).catch(() => {});
    expect(calls).toBe(3);
  });

  it('attempts 为 0 时一次都不调用', async () => {
    let calls = 0;
    await withRetry(async () => { calls += 1; return 'ok'; }, 0).catch(() => {});
    expect(calls).toBe(0);
  });

  it('全部失败时抛出最后一次错误', async () => {
    let calls = 0;
    const err = await withRetry(async () => {
      calls += 1;
      throw new Error(`err-${calls}`);
    }, 2).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(Error);
    expect((err as Error).message).toBe('err-2');
    expect(calls).toBe(2);
  });
});

